@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AISettingsScreen(navController: NavHostController) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()

    var keys by remember { mutableStateOf(GeminiKeyManager.getAllKeys(context)) }
    var activeKeyId by remember { mutableStateOf(GeminiKeyManager.getActiveKeyId(context)) }
    var isEnabled by remember { mutableStateOf(GeminiKeyManager.isEnabled(context)) }
    var showAddDialog by remember { mutableStateOf(false) }
    var editingKey by remember { mutableStateOf<GeminiApiKey?>(null) }
    var deletingKey by remember { mutableStateOf<GeminiApiKey?>(null) }

    fun refreshState() {
        keys = GeminiKeyManager.getAllKeys(context)
        activeKeyId = GeminiKeyManager.getActiveKeyId(context)
        isEnabled = GeminiKeyManager.isEnabled(context)
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("AI Settings", fontWeight = FontWeight.Bold) },
                navigationIcon = {
                    IconButton(onClick = { navController.popBackStack() }) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, "Back")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.background
                )
            )
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp)
        ) {
            // ──────────── Header Section ────────────
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.3f)
                ),
                shape = RoundedCornerShape(16.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text("", fontSize = 28.sp)
                        Spacer(modifier = Modifier.width(12.dp))
                        Column {
                            Text(
                                "Gemini Smart AI",
                                style = MaterialTheme.typography.titleMedium,
                                fontWeight = FontWeight.Bold
                            )
                            Text(
                                "Understands Hindi, Hinglish & complex reminders",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }

                    Spacer(modifier = Modifier.height(12.dp))

                    Text(
                        "Add your free Gemini API key to enable AI-powered reminder detection. " +
                                "Without it, the app still uses on-device ML Kit + patterns (handles 80% of cases).",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        lineHeight = 18.sp
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // ──────────── Enable/Disable Toggle ────────────
            if (keys.isNotEmpty()) {
                Card(
                    modifier = Modifier.fillMaxWidth(),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                "Enable Gemini AI",
                                style = MaterialTheme.typography.bodyLarge,
                                fontWeight = FontWeight.Medium
                            )
                            Text(
                                if (isEnabled) "Active — AI analyzes complex text" else "Disabled — using on-device only",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                        Switch(
                            checked = isEnabled,
                            onCheckedChange = {
                                GeminiKeyManager.setEnabled(context, it)
                                isEnabled = it
                                GeminiReminderParser.invalidate()
                            }
                        )
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))
            }

            // ──────────── API Keys Section ────────────
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    "API Keys",
                    style = MaterialTheme.typography.titleSmall,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.weight(1f)
                )
                TextButton(onClick = { showAddDialog = true }) {
                    Icon(Icons.Default.Add, null, modifier = Modifier.size(18.dp))
                    Spacer(modifier = Modifier.width(4.dp))
                    Text("Add Key")
                }
            }

            Spacer(modifier = Modifier.height(8.dp))

            if (keys.isEmpty()) {
                // Empty state
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable { showAddDialog = true },
                    colors = CardDefaults.cardColors(
                        containerColor = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
                    ),
                    shape = RoundedCornerShape(12.dp)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(24.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Icon(
                            Icons.Default.Key,
                            null,
                            modifier = Modifier.size(40.dp),
                            tint = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                        Spacer(modifier = Modifier.height(12.dp))
                        Text(
                            "No API keys added",
                            style = MaterialTheme.typography.bodyLarge,
                            fontWeight = FontWeight.Medium
                        )
                        Text(
                            "Tap to add your free Gemini API key",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                }
            } else {
                // Key list
                keys.forEach { key ->
                    ApiKeyCard(
                        key = key,
                        isActive = key.id == activeKeyId,
                        onSetActive = {
                            GeminiKeyManager.setActiveKeyId(context, key.id)
                            GeminiReminderParser.invalidate()
                            refreshState()
                        },
                        onEdit = { editingKey = key },
                        onDelete = { deletingKey = key }
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            // ──────────── How to Get Key Section ────────────
            Card(
                modifier = Modifier.fillMaxWidth(),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.tertiaryContainer.copy(alpha = 0.3f)
                ),
                shape = RoundedCornerShape(12.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text(
                        "How to get a free API key:",
                        style = MaterialTheme.typography.titleSmall,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    Text("1. Open aistudio.google.com/apikey", style = MaterialTheme.typography.bodySmall)
                    Text("2. Sign in with your Google account", style = MaterialTheme.typography.bodySmall)
                    Text("3. Click \"Create API Key\"", style = MaterialTheme.typography.bodySmall)
                    Text("4. Copy the key and paste it here", style = MaterialTheme.typography.bodySmall)
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(
                        "✨ It's completely free — 15 requests/minute, 1500/day",
                        style = MaterialTheme.typography.bodySmall,
                        fontWeight = FontWeight.Medium,
                        color = MaterialTheme.colorScheme.primary
                    )

                    Spacer(modifier = Modifier.height(12.dp))

                    TextButton(
                        onClick = {
                            val intent = Intent(Intent.ACTION_VIEW, Uri.parse("https://aistudio.google.com/apikey"))
                            context.startActivity(intent)
                        }
                    ) {
                        Icon(Icons.Default.OpenInNew, null, modifier = Modifier.size(16.dp))
                        Spacer(modifier = Modifier.width(6.dp))
                        Text("Open Google AI Studio")
                    }
                }
            }

            Spacer(modifier = Modifier.height(24.dp))

            // ──────────── Privacy Note ────────────
            Text(
                " Privacy: Your API key is stored encrypted on-device only. " +
                        "Note text is sent to Google's Gemini API only when on-device detection fails. " +
                        "No note content is ever stored by Google for training.",
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                lineHeight = 16.sp,
                modifier = Modifier.padding(horizontal = 4.dp)
            )

            Spacer(modifier = Modifier.height(32.dp))
        }
    }

    // ──────────── Add Key Dialog ────────────
    if (showAddDialog) {
        AddApiKeyDialog(
            onDismiss = { showAddDialog = false },
            onSave = { label, apiKey ->
                scope.launch {
                    val isValid = GeminiReminderParser.getInstance(context).validateApiKey(apiKey)
                    if (isValid) {
                        GeminiKeyManager.addApiKey(context, label, apiKey)
                        GeminiReminderParser.invalidate()
                        refreshState()
                        showAddDialog = false
                        Toast.makeText(context, "✅ API key added & verified!", Toast.LENGTH_SHORT).show()
                    } else {
                        Toast.makeText(context, "❌ Invalid API key. Please check and try again.", Toast.LENGTH_LONG).show()
                    }
                }
            }
        )
    }

    // ──────────── Edit Key Dialog ────────────
    editingKey?.let { key ->
        EditKeyLabelDialog(
            currentLabel = key.label,
            onDismiss = { editingKey = null },
            onSave = { newLabel ->
                GeminiKeyManager.updateKeyLabel(context, key.id, newLabel)
                refreshState()
                editingKey = null
            }
        )
    }

    // ──────────── Delete Confirmation ────────────
    deletingKey?.let { key ->
        AlertDialog(
            onDismissRequest = { deletingKey = null },
            title = { Text("Remove API Key?") },
            text = {
                Text("Remove \"${key.label}\"? This cannot be undone. You can always add it back later.")
            },
            confirmButton = {
                TextButton(onClick = {
                    GeminiKeyManager.removeApiKey(context, key.id)
                    GeminiReminderParser.invalidate()
                    refreshState()
                    deletingKey = null
                    Toast.makeText(context, "Key removed", Toast.LENGTH_SHORT).show()
                }) {
                    Text("Remove", color = MaterialTheme.colorScheme.error)
                }
            },
            dismissButton = {
                TextButton(onClick = { deletingKey = null }) {
                    Text("Cancel")
                }
            }
        )
    }
}

@Composable
private fun ApiKeyCard(
    key: GeminiApiKey,
    isActive: Boolean,
    onSetActive: () -> Unit,
    onEdit: () -> Unit,
    onDelete: () -> Unit
) {
    val clipboardManager = LocalClipboardManager.current
    val context = LocalContext.current

    Card(
        modifier = Modifier
            .fillMaxWidth()
            .animateContentSize(),
        colors = CardDefaults.cardColors(
            containerColor = if (isActive)
                MaterialTheme.colorScheme.primaryContainer.copy(alpha = 0.4f)
            else
                MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.4f)
        ),
        shape = RoundedCornerShape(12.dp)
    ) {
        Column(modifier = Modifier.padding(12.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                // Active indicator
                IconButton(
                    onClick = onSetActive,
                    modifier = Modifier.size(32.dp)
                ) {
                    Icon(
                        if (isActive) Icons.Default.RadioButtonChecked else Icons.Default.RadioButtonUnchecked,
                        contentDescription = if (isActive) "Active key" else "Set as active",
                        tint = if (isActive) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.size(20.dp)
                    )
                }

                Spacer(modifier = Modifier.width(8.dp))

                Column(modifier = Modifier.weight(1f)) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text(
                            key.label,
                            style = MaterialTheme.typography.bodyMedium,
                            fontWeight = FontWeight.Medium,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                        if (isActive) {
                            Spacer(modifier = Modifier.width(6.dp))
                            Text(
                                "ACTIVE",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.primary,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                    Text(
                        key.maskedKey,
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }

                // Actions
                IconButton(onClick = onEdit, modifier = Modifier.size(32.dp)) {
                    Icon(Icons.Default.Edit, "Edit label", modifier = Modifier.size(16.dp))
                }
                IconButton(onClick = onDelete, modifier = Modifier.size(32.dp)) {
                    Icon(
                        Icons.Default.Delete, "Delete key",
                        modifier = Modifier.size(16.dp),
                        tint = MaterialTheme.colorScheme.error
                    )
                }
            }

            // Usage stats
            if (key.usageCount > 0) {
                Spacer(modifier = Modifier.height(4.dp))
                val lastUsedStr = if (key.lastUsed > 0) {
                    SimpleDateFormat("MMM d, h:mm a", Locale.getDefault()).format(Date(key.lastUsed))
                } else "Never"
                Text(
                    "Used ${key.usageCount} times · Last: $lastUsedStr",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.padding(start = 40.dp)
                )
            }
        }
    }
}

@Composable
private fun AddApiKeyDialog(
    onDismiss: () -> Unit,
    onSave: (label: String, apiKey: String) -> Unit
) {
    var label by remember { mutableStateOf("") }
    var apiKey by remember { mutableStateOf("") }
    var keyVisible by remember { mutableStateOf(false) }
    var isValidating by remember { mutableStateOf(false) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("Add Gemini API Key") },
        text = {
            Column {
                Text(
                    "Get your free key from aistudio.google.com/apikey",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.primary
                )

                Spacer(modifier = Modifier.height(16.dp))

                OutlinedTextField(
                    value = label,
                    onValueChange = { label = it },
                    label = { Text("Label (optional)") },
                    placeholder = { Text("e.g., Personal, Work, Backup") },
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth()
                )

                Spacer(modifier = Modifier.height(12.dp))

                OutlinedTextField(
                    value = apiKey,
                    onValueChange = { apiKey = it },
                    label = { Text("API Key") },
                    placeholder = { Text("AIzaSy...") },
                    singleLine = true,
                    modifier = Modifier.fillMaxWidth(),
                    visualTransformation = if (keyVisible) VisualTransformation.None else PasswordVisualTransformation(),
                    trailingIcon = {
                        IconButton(onClick = { keyVisible = !keyVisible }) {
                            Icon(
                                if (keyVisible) Icons.Default.VisibilityOff else Icons.Default.Visibility,
                                contentDescription = "Toggle visibility"
                            )
                        }
                    }
                )

                if (isValidating) {
                    Spacer(modifier = Modifier.height(12.dp))
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp)
                        Spacer(modifier = Modifier.width(8.dp))
                        Text("Validating key...", style = MaterialTheme.typography.bodySmall)
                    }
                }
            }
        },
        confirmButton = {
            TextButton(
                onClick = {
                    isValidating = true
                    onSave(label, apiKey)
                },
                enabled = apiKey.length >= 10 && !isValidating
            ) {
                Text("Validate & Save")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Cancel") }
        }
    )
}

@Composable
private fun EditKeyLabelDialog(
    currentLabel: String,
    onDismiss: () -> Unit,
    onSave: (String) -> Unit
) {
    var newLabel by remember { mutableStateOf(currentLabel) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("Edit Key Label") },
        text = {
            OutlinedTextField(
                value = newLabel,
                onValueChange = { newLabel = it },
                label = { Text("Label") },
                singleLine = true,
                modifier = Modifier.fillMaxWidth()
            )
        },
        confirmButton = {
            TextButton(
                onClick = { onSave(newLabel) },
                enabled = newLabel.isNotBlank()
            ) { Text("Save") }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text("Cancel") }
        }
    )
}

