import androidx.compose.runtime.remember
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.glance.GlanceId
import androidx.glance.GlanceModifier
import androidx.glance.Image
import androidx.glance.ImageProvider
import androidx.glance.LocalContext
import androidx.glance.LocalSize
import androidx.glance.action.ActionParameters
import androidx.glance.action.actionParametersOf
import androidx.glance.action.clickable
import androidx.glance.appwidget.GlanceAppWidget
import androidx.glance.appwidget.SizeMode
import androidx.glance.appwidget.action.ActionCallback
import androidx.glance.appwidget.action.actionRunCallback
import androidx.glance.appwidget.cornerRadius
import androidx.glance.appwidget.lazy.LazyColumn
import androidx.glance.appwidget.lazy.itemsIndexed
import androidx.glance.appwidget.provideContent
import androidx.glance.background
import androidx.glance.color.ColorProvider
import androidx.glance.layout.Alignment
import androidx.glance.layout.Box
import androidx.glance.layout.Column
import androidx.glance.layout.Row
import androidx.glance.layout.Spacer
import androidx.glance.layout.fillMaxSize
import androidx.glance.layout.fillMaxWidth
import androidx.glance.layout.height
import androidx.glance.layout.padding
import androidx.glance.layout.size
import androidx.glance.layout.width
import androidx.glance.text.FontWeight
import androidx.glance.text.Text
import androidx.glance.text.TextAlign
import androidx.glance.text.TextStyle
import com.amvarpvtltd.swiftNote.MainActivity
import com.amvarpvtltd.swiftNote.R
import com.amvarpvtltd.swiftNote.dataclass
import com.amvarpvtltd.swiftNote.room.AppDatabase
import com.amvarpvtltd.swiftNote.room.NoteEntityMapper
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import kotlinx.coroutines.flow.map as flowMap

/**
 * SwiftNote Home Screen Widget
 *
 * Design principles:
 *  • UNIFIED layout — same visual structure at all sizes, just scales content
 *  • CONSISTENT spacing — uniform 16dp padding, 12dp gaps
 *  • CLEAN typography — 14sp titles, 12sp body, 10sp muted
 *  • MODERN cards — 16dp radius, subtle elevation via color
 *  • RESPONSIVE — shows pinned notes when height allows (≥ 160dp)
 */
class QuickNoteWidget : GlanceAppWidget() {

    companion object {
        val ACTION_KEY  = ActionParameters.Key<String>("widget_action")
        val NOTE_ID_KEY = ActionParameters.Key<String>("widget_note_id")

        const val ACTION_CREATE_NOTE      = "com.amvarpvtltd.swiftNote.ACTION_CREATE_NOTE"
        const val ACTION_CREATE_CHECKLIST = "com.amvarpvtltd.swiftNote.ACTION_CREATE_CHECKLIST"
        const val ACTION_OPEN_NOTE        = "com.amvarpvtltd.swiftNote.ACTION_OPEN_NOTE"
        const val ACTION_OPEN_APP         = "com.amvarpvtltd.swiftNote.ACTION_OPEN_APP"

        // ─── Design tokens ─────────────────────────────────────────────────
        private val CORNER_RADIUS = 20.dp
        private val CARD_RADIUS = 14.dp
        private val BUTTON_RADIUS = 12.dp
        private val PADDING = 16.dp
        private val GAP = 12.dp
        private val CARD_GAP = 10.dp

        // Height threshold to show pinned notes section
        private val SHOW_NOTES_THRESHOLD = 160.dp

        // Accent colors for note cards (rotating)
        private val ACCENT_COLORS = listOf(
            Color(0xFF6366F1), // Indigo
            Color(0xFF8B5CF6), // Purple
            Color(0xFF06B6D4), // Cyan
            Color(0xFF10B981), // Emerald
            Color(0xFFF59E0B), // Amber
        )

        // ─── Color palette (light / dark) ──────────────────────────────────
        private val BgColor        = ColorProvider(Color(0xFFF8FAFC), Color(0xFF0F1419))
        private val SurfaceColor   = ColorProvider(Color(0xFFFFFFFF), Color(0xFF1C2128))
        private val SurfaceAltColor= ColorProvider(Color(0xFFF1F5F9), Color(0xFF21262D))
        private val PrimaryColor   = ColorProvider(Color(0xFF6366F1), Color(0xFF818CF8))
        private val PrimaryBtnBg   = ColorProvider(Color(0xFF6366F1), Color(0xFF4F46E5))
        private val PrimaryBtnText = ColorProvider(Color(0xFFFFFFFF), Color(0xFFFFFFFF))
        private val SecBtnBg       = ColorProvider(Color(0xFFE0E7FF), Color(0xFF312E81))
        private val SecBtnText     = ColorProvider(Color(0xFF4338CA), Color(0xFFC7D2FE))
        private val TitleColor     = ColorProvider(Color(0xFF0F172A), Color(0xFFF0F6FC))
        private val BodyColor      = ColorProvider(Color(0xFF475569), Color(0xFF8B949E))
        private val MutedColor     = ColorProvider(Color(0xFF94A3B8), Color(0xFF6E7681))
    }

    override val sizeMode = SizeMode.Exact

    override suspend fun provideGlance(context: Context, id: GlanceId) {
        provideContent {
            val ctx = LocalContext.current
            val db = remember { AppDatabase.getInstance(ctx) }

            val pinnedFlow = remember(db) {
                db.noteDao()
                    .observePinnedNotes()
                    .flowMap { entities -> entities.map { NoteEntityMapper.toDomain(it) } }
            }
            val pinnedNotes by pinnedFlow.collectAsState(initial = emptyList())

            val countFlow = remember(db) { db.noteDao().observeNoteCount() }
            val totalNotes by countFlow.collectAsState(initial = 0)

            WidgetContent(pinnedNotes, totalNotes)
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // MAIN CONTENT — Unified layout for all sizes
    // ═══════════════════════════════════════════════════════════════════════

    @Composable
    private fun WidgetContent(pinnedNotes: List<dataclass>, totalNotes: Int) {
        val size = LocalSize.current
        val showNotes = size.height >= SHOW_NOTES_THRESHOLD && pinnedNotes.isNotEmpty()

        Box(
            modifier = GlanceModifier
                .fillMaxSize()
                .cornerRadius(CORNER_RADIUS)
                .background(BgColor)
                .padding(PADDING)
        ) {
            Column(modifier = GlanceModifier.fillMaxSize()) {
                // ─── Header ────────────────────────────────────────────────
                Header(totalNotes)

                Spacer(modifier = GlanceModifier.height(GAP))

                // ─── Action Buttons ────────────────────────────────────────
                ActionButtons()

                // ─── Pinned Notes (if space allows) ────────────────────────
                if (showNotes) {
                    Spacer(modifier = GlanceModifier.height(GAP))
                    PinnedNotesSection(pinnedNotes)
                } else if (totalNotes == 0 && size.height >= SHOW_NOTES_THRESHOLD) {
                    Spacer(modifier = GlanceModifier.height(GAP))
                    EmptyState()
                }
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // HEADER — App icon, title, note count, open button
    // ═══════════════════════════════════════════════════════════════════════

    @Composable
    private fun Header(totalNotes: Int) {
        Row(
            modifier = GlanceModifier
                .fillMaxWidth()
                .clickable(actionRunCallback<WidgetActionCallback>(
                    actionParametersOf(ACTION_KEY to ACTION_OPEN_APP)
                )),
            verticalAlignment = Alignment.CenterVertically
        ) {
            // App icon
            Box(
                modifier = GlanceModifier
                    .size(36.dp)
                    .cornerRadius(10.dp)
                    .background(PrimaryColor),
                contentAlignment = Alignment.Center
            ) {
                Image(
                    provider = ImageProvider(R.drawable.logo2),
                    contentDescription = "SwiftNote",
                    modifier = GlanceModifier.size(22.dp)
                )
            }

            Spacer(modifier = GlanceModifier.width(10.dp))

            // Title + count
            Column(modifier = GlanceModifier.defaultWeight()) {
                Text(
                    "SwiftNote",
                    style = TextStyle(
                        fontWeight = FontWeight.Bold,
                        fontSize = 15.sp,
                        color = TitleColor
                    )
                )
                if (totalNotes > 0) {
                    Text(
                        "$totalNotes notes",
                        style = TextStyle(fontSize = 11.sp, color = MutedColor)
                    )
                }
            }

            // Open button
            Box(
                modifier = GlanceModifier
                    .cornerRadius(BUTTON_RADIUS)
                    .background(SurfaceAltColor)
                    .padding(horizontal = 12.dp, vertical = 6.dp)
                    .clickable(actionRunCallback<WidgetActionCallback>(
                        actionParametersOf(ACTION_KEY to ACTION_OPEN_APP)
                    ))
            ) {
                Text(
                    "Open",
                    style = TextStyle(
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Medium,
                        color = BodyColor
                    )
                )
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ACTION BUTTONS — Always consistent, adapts label based on width
    // ═══════════════════════════════════════════════════════════════════════

    @Composable
    private fun ActionButtons() {
        val width = LocalSize.current.width
        // Short labels for narrow widgets (< 220dp)
        val useShortLabels = width < 220.dp

        Row(
            modifier = GlanceModifier.fillMaxWidth(),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // New Note button
            ActionButton(
                label = if (useShortLabels) "Note" else "New Note",
                icon = "✏️",
                isPrimary = true,
                action = ACTION_CREATE_NOTE,
                modifier = GlanceModifier.defaultWeight()
            )

            Spacer(modifier = GlanceModifier.width(10.dp))

            // Checklist button
            ActionButton(
                label = if (useShortLabels) "List" else "Checklist",
                icon = "☑️",
                isPrimary = false,
                action = ACTION_CREATE_CHECKLIST,
                modifier = GlanceModifier.defaultWeight()
            )
        }
    }

    @Composable
    private fun ActionButton(
        label: String,
        icon: String,
        isPrimary: Boolean,
        action: String,
        modifier: GlanceModifier
    ) {
        val bgColor = if (isPrimary) PrimaryBtnBg else SecBtnBg
        val textColor = if (isPrimary) PrimaryBtnText else SecBtnText

        Box(
            modifier = modifier
                .cornerRadius(BUTTON_RADIUS)
                .background(bgColor)
                .padding(vertical = 12.dp, horizontal = 12.dp)
                .clickable(actionRunCallback<WidgetActionCallback>(
                    actionParametersOf(ACTION_KEY to action)
                )),
            contentAlignment = Alignment.Center
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(icon, style = TextStyle(fontSize = 14.sp))
                Spacer(modifier = GlanceModifier.width(6.dp))
                Text(
                    label,
                    style = TextStyle(
                        fontSize = 13.sp,
                        fontWeight = FontWeight.Bold,
                        color = textColor
                    )
                )
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // PINNED NOTES SECTION — Scrollable list with proper spacing
    // ═══════════════════════════════════════════════════════════════════════

    @Composable
    private fun PinnedNotesSection(notes: List<dataclass>) {
        Column(modifier = GlanceModifier.fillMaxSize()) {
            // Section header
            Row(
                modifier = GlanceModifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    "  PINNED",
                    style = TextStyle(
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        color = MutedColor
                    )
                )
                Spacer(modifier = GlanceModifier.width(8.dp))
                Box(
                    modifier = GlanceModifier
                        .cornerRadius(8.dp)
                        .background(SecBtnBg)
                        .padding(horizontal = 6.dp, vertical = 2.dp)
                ) {
                    Text(
                        "${notes.size}",
                        style = TextStyle(
                            fontSize = 10.sp,
                            fontWeight = FontWeight.Bold,
                            color = SecBtnText
                        )
                    )
                }
            }

            Spacer(modifier = GlanceModifier.height(10.dp))

            // Scrollable notes list with proper spacing
            LazyColumn(modifier = GlanceModifier.fillMaxSize()) {
                itemsIndexed(notes) { index, note ->
                    NoteCard(note, index, isLast = index == notes.lastIndex)
                }
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // NOTE CARD — Clean, consistent card design
    // ═══════════════════════════════════════════════════════════════════════

    @Composable
    private fun NoteCard(note: dataclass, index: Int) {
        val accentColor = ColorProvider(
            ACCENT_COLORS[index % ACCENT_COLORS.size],
            ACCENT_COLORS[index % ACCENT_COLORS.size]
        )
        val timeStr = formatRelativeTime(note.updatedAt)
        val hasChecklist = note.description.startsWith("[[CHECKLIST_V1]]")

        Box(
            modifier = GlanceModifier
                .fillMaxWidth()
                .cornerRadius(CARD_RADIUS)
                .background(SurfaceColor)
                .clickable(actionRunCallback<WidgetActionCallback>(
                    actionParametersOf(ACTION_KEY to ACTION_OPEN_NOTE, NOTE_ID_KEY to note.id)
                ))
        ) {
            Row(
                modifier = GlanceModifier
                    .fillMaxWidth()
                    .padding(12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Accent indicator
                Box(
                    modifier = GlanceModifier
                        .size(width = 4.dp, height = 36.dp)
                        .cornerRadius(2.dp)
                        .background(accentColor)
                ) {}

                Spacer(modifier = GlanceModifier.width(12.dp))

                // Content
                Column(modifier = GlanceModifier.defaultWeight()) {
                    // Title with optional checklist icon
                    Text(
                        text = if (hasChecklist) "☑ ${note.title.take(28).ifEmpty { "Untitled" }}"
                               else note.title.take(32).ifEmpty { "Untitled" },
                        style = TextStyle(
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold,
                            color = TitleColor
                        ),
                        maxLines = 1
                    )

                    // Description preview (only for non-checklist notes)
                    if (!hasChecklist && note.description.isNotBlank()) {
                        Spacer(modifier = GlanceModifier.height(2.dp))
                        Text(
                            text = note.description.take(40).replace("\n", " "),
                            style = TextStyle(fontSize = 11.sp, color = BodyColor),
                            maxLines = 1
                        )
                    }

                    // Timestamp
                    if (timeStr.isNotEmpty()) {
                        Spacer(modifier = GlanceModifier.height(4.dp))
                        Text(
                            text = timeStr,
                            style = TextStyle(fontSize = 10.sp, color = MutedColor)
                        )
                    }
                }

                // Chevron
                Text(
                    "›",
                    style = TextStyle(
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Medium,
                        color = MutedColor
                    )
                )
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // EMPTY STATE
    // ═══════════════════════════════════════════════════════════════════════

    @Composable
    private fun EmptyState() {
        Box(
            modifier = GlanceModifier
                .fillMaxWidth()
                .cornerRadius(CARD_RADIUS)
                .background(SurfaceAltColor)
                .padding(20.dp)
                .clickable(actionRunCallback<WidgetActionCallback>(
                    actionParametersOf(ACTION_KEY to ACTION_CREATE_NOTE)
                )),
            contentAlignment = Alignment.Center
        ) {
            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                Text("", style = TextStyle(fontSize = 24.sp))
                Spacer(modifier = GlanceModifier.height(8.dp))
                Text(
                    "No notes yet",
                    style = TextStyle(
                        fontSize = 14.sp,
                        fontWeight = FontWeight.Bold,
                        color = TitleColor
                    )
                )
                Spacer(modifier = GlanceModifier.height(4.dp))
                Text(
                    "Tap to create your first note",
                    style = TextStyle(
                        fontSize = 12.sp,
                        color = BodyColor,
                        textAlign = TextAlign.Center
                    )
                )
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // HELPERS
    // ═══════════════════════════════════════════════════════════════════════

    private fun formatRelativeTime(timestamp: Long): String {
        if (timestamp <= 0) return ""
        val diff = System.currentTimeMillis() - timestamp
        return when {
            diff < 60_000       -> "just now"
            diff < 3_600_000    -> "${diff / 60_000}m ago"
            diff < 86_400_000   -> "${diff / 3_600_000}h ago"
            diff < 604_800_000  -> "${diff / 86_400_000}d ago"
            else -> SimpleDateFormat("MMM d", Locale.getDefault()).format(Date(timestamp))
        }
    }
}

/**
 * ActionCallback — launches MainActivity with the correct action + optional noteId.
 */
class WidgetActionCallback : ActionCallback {
    override suspend fun onAction(
        context: Context,
        glanceId: GlanceId,
        parameters: ActionParameters
    ) {
        val action = parameters[QuickNoteWidget.ACTION_KEY] ?: return
        val noteId = parameters[QuickNoteWidget.NOTE_ID_KEY]
        context.startActivity(
            Intent(context, MainActivity::class.java).apply {
                this.action = action
                noteId?.let { putExtra("noteId", it) }
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
            }
        )
    }
}

package com.amvarpvtltd.swiftNote.reminders

import android.Manifest
import android.annotation.SuppressLint
import android.app.AlarmManager
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.os.Build
import android.util.Log
import androidx.annotation.RequiresPermission
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import com.amvarpvtltd.swiftNote.MainActivity
import com.amvarpvtltd.swiftNote.R
import com.amvarpvtltd.swiftNote.ai.DetectedReminder
import com.amvarpvtltd.swiftNote.room.AppDatabase
import kotlinx.coroutines.CoroutineExceptionHandler
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * Manages reminders with persistent alarms that survive device reboots
 */
class ReminderManager private constructor(private val context: Context) {
    private val TAG = "ReminderManager"

    private val alarmManager = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
    private val database = AppDatabase.getInstance(context)
    private val reminderDao = database.reminderDao()

    private val exceptionHandler = CoroutineExceptionHandler { _, exception ->
        Log.e(TAG, "Uncaught exception in ReminderManager scope", exception)
    }
    private val managerScope = CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler)

    companion object {
        @SuppressLint("StaticFieldLeak")
        @Volatile
        private var INSTANCE: ReminderManager? = null

        private const val NOTIFICATION_CHANNEL_ID = "smart_reminders"
        private const val NOTIFICATION_CHANNEL_NAME = "Smart Reminders"

        const val EXTRA_REMINDER_ID = "reminder_id"
        const val EXTRA_REMINDER_TITLE = "reminder_title"
        const val EXTRA_REMINDER_DESCRIPTION = "reminder_description"
        const val EXTRA_NOTE_ID = "note_id"

        fun getInstance(context: Context): ReminderManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: ReminderManager(context.applicationContext).also {
                    INSTANCE = it
                    it.createNotificationChannel()
                }
            }
        }
    }

    /**
     * Create notification channel for reminders
     */
    private fun createNotificationChannel() {
        val channel = NotificationChannel(
            NOTIFICATION_CHANNEL_ID,
            NOTIFICATION_CHANNEL_NAME,
            NotificationManager.IMPORTANCE_HIGH
        ).apply {
            description = "Notifications for smart reminders from your notes"
            enableVibration(true)
            enableLights(true)
            setShowBadge(true)
        }

        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        notificationManager.createNotificationChannel(channel)
        Log.d(TAG, " Notification channel created")
    }

    /**
     * Schedule a reminder alarm
     */
    suspend fun scheduleReminder(
        reminder: DetectedReminder,
        noteId: String
    ): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            // Check if we can schedule exact alarms
            if (!canScheduleExactAlarms()) {
                // Don't fail hard if exact alarm permission isn't granted. Persist the reminder
                // and schedule a best-effort alarm. This ensures reminders are created even when
                // the system restricts exact alarms (app may request permission separately).
                Log.w(TAG, "⚠️ Exact alarm permission not granted — falling back to best-effort scheduling")
            }

            // Save reminder to database - Fixed field names to match ReminderEntity
            val reminderEntity = ReminderEntity(
                id = reminder.id,
                noteId = noteId,
                noteTitle = reminder.title,
                noteDescription = reminder.description,
                reminderTime = reminder.reminderDateTime,
                isActive = true,
                createdAt = System.currentTimeMillis()
            )

            reminderDao.insertReminder(reminderEntity) // Fixed method name
            Log.d(TAG, " Reminder saved to database: ${reminder.title}")

            // Schedule the alarm
            val intent = Intent(context, ReminderReceiver::class.java).apply {
                putExtra(EXTRA_REMINDER_ID, reminder.id)
                putExtra(EXTRA_REMINDER_TITLE, reminder.title)
                putExtra(EXTRA_REMINDER_DESCRIPTION, reminder.description)
                putExtra(EXTRA_NOTE_ID, noteId)
            }

            val pendingIntent = PendingIntent.getBroadcast(
                context,
                reminder.id.hashCode(),
                intent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            // Schedule exact alarm if possible, otherwise schedule a best-effort alarm
            try {
                if (canScheduleExactAlarms()) {
                    alarmManager.setExactAndAllowWhileIdle(
                        AlarmManager.RTC_WAKEUP,
                        reminder.reminderDateTime,
                        pendingIntent
                    )
                } else {
                    // Best-effort fallback using set which may be inexact but still fires
                    alarmManager.set(
                        AlarmManager.RTC_WAKEUP,
                        reminder.reminderDateTime,
                        pendingIntent
                    )
                }
            } catch (e: SecurityException) {
                Log.w(TAG, "⚠️ SecurityException scheduling alarm, skipping alarm scheduling: ${e.message}")
            }

            val formatter = SimpleDateFormat("MMM dd, yyyy 'at' hh:mm a", Locale.getDefault())
            val dateTime = formatter.format(Date(reminder.reminderDateTime))

            Log.d(TAG, "⏰ Reminder scheduled: ${reminder.title} for $dateTime")
            Result.success("Reminder scheduled for $dateTime")

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error scheduling reminder", e)
            Result.failure(e)
        }
    }

    /**
     * Get all active reminders
     */
    suspend fun getAllActiveReminders(): List<ReminderEntity> = withContext(Dispatchers.IO) {
        return@withContext try {
            reminderDao.getAllActiveReminders().first()
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error getting all active reminders", e)
            emptyList()
        }
    }

    /**
     * Reschedule all active reminders (called after device reboot)
     */
    suspend fun rescheduleAllReminders(): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            val activeReminders = getAllActiveReminders() // Use the corrected method
            val currentTime = System.currentTimeMillis()
            var rescheduledCount = 0

            activeReminders.forEach { reminder ->
                if (reminder.reminderTime > currentTime) { // Fixed field name
                    // Reschedule future reminders
                    val intent = Intent(context, ReminderReceiver::class.java).apply {
                        putExtra(EXTRA_REMINDER_ID, reminder.id)
                        putExtra(EXTRA_REMINDER_TITLE, reminder.noteTitle) // Fixed field name
                        putExtra(EXTRA_REMINDER_DESCRIPTION, reminder.noteDescription) // Fixed field name
                        putExtra(EXTRA_NOTE_ID, reminder.noteId)
                    }

                    val pendingIntent = PendingIntent.getBroadcast(
                        context,
                        reminder.id.hashCode(),
                        intent,
                        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                    )

                    // Schedule exact alarm if possible, otherwise use best-effort fallback
                    try {
                        if (canScheduleExactAlarms()) {
                            alarmManager.setExactAndAllowWhileIdle(
                                AlarmManager.RTC_WAKEUP,
                                reminder.reminderTime,
                                pendingIntent
                            )
                        } else {
                            alarmManager.set(
                                AlarmManager.RTC_WAKEUP,
                                reminder.reminderTime,
                                pendingIntent
                            )
                        }
                    } catch (e: SecurityException) {
                        Log.w(TAG, "⚠️ SecurityException rescheduling alarm for ${reminder.id}: ${e.message}")
                        // Best-effort fallback
                        alarmManager.set(
                            AlarmManager.RTC_WAKEUP,
                            reminder.reminderTime,
                            pendingIntent
                        )
                    }
                    rescheduledCount++
                } else {
                    // Mark expired reminders as inactive - Fixed using deactivateReminder
                    reminderDao.deactivateReminder(reminder.id)
                }
            }

            Log.d(TAG, " Rescheduled $rescheduledCount reminders after reboot")
            Result.success("Rescheduled $rescheduledCount reminders")

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error rescheduling reminders", e)
            Result.failure(e)
        }
    }

    /**
     * Create a reminder from AI detection
     * This is a convenience method that wraps scheduleReminder with proper error handling
     */
    suspend fun createReminderFromDetection(
        detectedReminder: DetectedReminder,
        noteId: String
    ): Boolean {
        return try {
            val result = scheduleReminder(detectedReminder, noteId)
            result.isSuccess
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error creating reminder from detection", e)
            false
        }
    }

    /**
     * Check if the app can schedule exact alarms
     */
    fun canScheduleExactAlarms(): Boolean {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            alarmManager.canScheduleExactAlarms()
        } else {
            true
        }
    }

    /**
     * Open system settings to allow the user to grant exact alarm permission (Android 12+).
     * Returns true if the intent was launched, false if not needed or not applicable.
     */
    fun requestExactAlarmPermission(): Boolean {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S && !canScheduleExactAlarms()) {
            try {
                val intent = Intent(
                    android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,
                    android.net.Uri.parse("package:${context.packageName}")
                ).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
                context.startActivity(intent)
                return true
            } catch (e: Exception) {
                Log.e(TAG, "❌ Error opening exact alarm settings", e)
            }
        }
        return false
    }

    /**
     * Show notification for triggered reminder
     */
    fun showReminderNotification(
        reminderId: String,
        title: String,
        description: String,
        noteId: String
    ) {
        try {
            // Check notification permissions first
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                val notificationManager = NotificationManagerCompat.from(context)
                if (!notificationManager.areNotificationsEnabled()) {
                    Log.w(TAG, "⚠️ Notifications are disabled for this app")
                    return
                }
            }

            // Create intent to open the note
            val notificationIntent = Intent(context, MainActivity::class.java).apply {
                putExtra("noteId", noteId)
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
            }

            val pendingIntent = PendingIntent.getActivity(
                context,
                reminderId.hashCode(),
                notificationIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            val notification = NotificationCompat.Builder(context, NOTIFICATION_CHANNEL_ID)
                .setSmallIcon( R.drawable.logo2)
                .setContentTitle(" $title")
                .setContentText(description)
                .setPriority(NotificationCompat.PRIORITY_HIGH)
                .setCategory(NotificationCompat.CATEGORY_REMINDER)
                .setAutoCancel(true)
                .setContentIntent(pendingIntent)
                .setVibrate(longArrayOf(0, 500, 100, 500))
                .setDefaults(NotificationCompat.DEFAULT_SOUND or NotificationCompat.DEFAULT_LIGHTS)
                .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
                .setOnlyAlertOnce(false)
                .build()

            val notificationManager = NotificationManagerCompat.from(context)
            try {
                notificationManager.notify(reminderId.hashCode(), notification)
                Log.d(TAG, " Reminder notification shown: $title")

                // Mark reminder as completed in database - Fixed using deactivateReminder
                managerScope.launch {
                    try {
                        reminderDao.deactivateReminder(reminderId)
                        Log.d(TAG, "✅ Reminder marked as completed: $title")
                    } catch (e: Exception) {
                        Log.e(TAG, "❌ Error marking reminder as completed", e)
                    }
                }
            } catch (e: SecurityException) {
                Log.e(TAG, "❌ Missing notification permission", e)
            }

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error showing reminder notification", e)
        }
    }
}

/**
 * BroadcastReceiver to handle reminder alarms
 */
class ReminderReceiver : BroadcastReceiver() {
    @RequiresPermission(Manifest.permission.POST_NOTIFICATIONS)
    override fun onReceive(context: Context, intent: Intent) {
        val reminderId = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_ID) ?: return
        val title = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_TITLE) ?: "Reminder"
        val description = intent.getStringExtra(ReminderManager.EXTRA_REMINDER_DESCRIPTION) ?: ""
        val noteId = intent.getStringExtra(ReminderManager.EXTRA_NOTE_ID) ?: ""

        Log.d("ReminderReceiver", " Reminder triggered: $title")

        val reminderManager = ReminderManager.getInstance(context)
        reminderManager.showReminderNotification(reminderId, title, description, noteId)
    }
}

/**
 * BroadcastReceiver to handle device boot and reschedule alarms
 */
class BootReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (Intent.ACTION_BOOT_COMPLETED == intent.action ||
            Intent.ACTION_MY_PACKAGE_REPLACED == intent.action) {

            Log.d("BootReceiver", " Device booted, rescheduling reminders...")

            val exceptionHandler = CoroutineExceptionHandler { _, exception ->
                Log.e("BootReceiver", "Uncaught exception in BootReceiver scope", exception)
            }
            CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler).launch {
                val reminderManager = ReminderManager.getInstance(context)
                reminderManager.rescheduleAllReminders()
            }
        }
    }
}

package com.amvarpvtltd.swiftNote.reminders

import android.Manifest
import android.annotation.SuppressLint
import android.app.AlarmManager
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.os.Build
import android.util.Log
import androidx.annotation.RequiresPermission
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import androidx.work.OneTimeWorkRequestBuilder
import androidx.work.WorkManager
import androidx.work.workDataOf
import com.amvarpvtltd.swiftNote.MainActivity
import com.amvarpvtltd.swiftNote.R
import com.amvarpvtltd.swiftNote.ai.DetectedReminder
import com.amvarpvtltd.swiftNote.room.AppDatabase
import kotlinx.coroutines.CoroutineExceptionHandler
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.concurrent.TimeUnit

/**
 * Manages reminders with persistent alarms that survive device reboots
 */
class ReminderManager private constructor(private val context: Context) {
    private val TAG = "ReminderManager"

    private val alarmManager = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
    private val database = AppDatabase.getInstance(context)
    private val reminderDao = database.reminderDao()

    private val exceptionHandler = CoroutineExceptionHandler { _, exception ->
        Log.e(TAG, "Uncaught exception in ReminderManager scope", exception)
    }
    private val managerScope = CoroutineScope(Dispatchers.IO + SupervisorJob() + exceptionHandler)

    companion object {
        @SuppressLint("StaticFieldLeak")
        @Volatile
        private var INSTANCE: ReminderManager? = null

        private const val NOTIFICATION_CHANNEL_ID = "smart_reminders"
        private const val NOTIFICATION_CHANNEL_NAME = "Smart Reminders"

        const val EXTRA_REMINDER_ID = "reminder_id"
        const val EXTRA_REMINDER_TITLE = "reminder_title"
        const val EXTRA_REMINDER_DESCRIPTION = "reminder_description"
        const val EXTRA_NOTE_ID = "note_id"

        fun getInstance(context: Context): ReminderManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: ReminderManager(context.applicationContext).also {
                    INSTANCE = it
                    it.createNotificationChannel()
                }
            }
        }
    }

    /**
     * Create notification channel for reminders
     */
    private fun createNotificationChannel() {
        val channel = NotificationChannel(
            NOTIFICATION_CHANNEL_ID,
            NOTIFICATION_CHANNEL_NAME,
            NotificationManager.IMPORTANCE_HIGH
        ).apply {
            description = "Notifications for smart reminders from your notes"
            enableVibration(true)
            enableLights(true)
            setShowBadge(true)
        }

        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        notificationManager.createNotificationChannel(channel)
        Log.d(TAG, " Notification channel created")
    }

    /**
     * Schedule a reminder alarm
     */
    suspend fun scheduleReminder(
        reminder: DetectedReminder,
        noteId: String
    ): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            // Check if we can schedule exact alarms
            if (!canScheduleExactAlarms()) {
                // Don't fail hard if exact alarm permission isn't granted. Persist the reminder
                // and schedule a best-effort alarm. This ensures reminders are created even when
                // the system restricts exact alarms (app may request permission separately).
                Log.w(TAG, "⚠️ Exact alarm permission not granted — falling back to best-effort scheduling")
            }

            // Save reminder to database - Fixed field names to match ReminderEntity
            val reminderEntity = ReminderEntity(
                id = reminder.id,
                noteId = noteId,
                noteTitle = reminder.title,
                noteDescription = reminder.description,
                reminderTime = reminder.reminderDateTime,
                isActive = true,
                createdAt = System.currentTimeMillis()
            )

            reminderDao.insertReminder(reminderEntity) // Fixed method name
            Log.d(TAG, " Reminder saved to database: ${reminder.title}")

            // Schedule the alarm
            val intent = Intent(context, ReminderReceiver::class.java).apply {
                putExtra(EXTRA_REMINDER_ID, reminder.id)
                putExtra(EXTRA_REMINDER_TITLE, reminder.title)
                putExtra(EXTRA_REMINDER_DESCRIPTION, reminder.description)
                putExtra(EXTRA_NOTE_ID, noteId)
            }

            val pendingIntent = PendingIntent.getBroadcast(
                context,
                reminder.id.hashCode(),
                intent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            // Schedule exact alarm if possible, otherwise schedule a best-effort alarm
            try {
                if (canScheduleExactAlarms()) {
                    alarmManager.setExactAndAllowWhileIdle(
                        AlarmManager.RTC_WAKEUP,
                        reminder.reminderDateTime,
                        pendingIntent
                    )
                } else {
                    // Best-effort fallback using set which may be inexact but still fires
                    alarmManager.set(
                        AlarmManager.RTC_WAKEUP,
                        reminder.reminderDateTime,
                        pendingIntent
                    )
                }
            } catch (e: SecurityException) {
                Log.w(TAG, "⚠️ SecurityException scheduling alarm, skipping alarm scheduling: ${e.message}")
            }

            val formatter = SimpleDateFormat("MMM dd, yyyy 'at' hh:mm a", Locale.getDefault())
            val dateTime = formatter.format(Date(reminder.reminderDateTime))

            Log.d(TAG, "⏰ Reminder scheduled: ${reminder.title} for $dateTime")
            Result.success("Reminder scheduled for $dateTime")

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error scheduling reminder", e)
            Result.failure(e)
        }
    }

    /**
     * Get all active reminders
     */
    suspend fun getAllActiveReminders(): List<ReminderEntity> = withContext(Dispatchers.IO) {
        return@withContext try {
            reminderDao.getAllActiveReminders().first()
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error getting all active reminders", e)
            emptyList()
        }
    }

    /**
     * Reschedule all active reminders (called after device reboot)
     */
    suspend fun rescheduleAllReminders(): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            val activeReminders = getAllActiveReminders() // Use the corrected method
            val currentTime = System.currentTimeMillis()
            var rescheduledCount = 0

            activeReminders.forEach { reminder ->
                if (reminder.reminderTime > currentTime) { // Fixed field name
                    // Reschedule future reminders
                    val intent = Intent(context, ReminderReceiver::class.java).apply {
                        putExtra(EXTRA_REMINDER_ID, reminder.id)
                        putExtra(EXTRA_REMINDER_TITLE, reminder.noteTitle) // Fixed field name
                        putExtra(EXTRA_REMINDER_DESCRIPTION, reminder.noteDescription) // Fixed field name
                        putExtra(EXTRA_NOTE_ID, reminder.noteId)
                    }

                    val pendingIntent = PendingIntent.getBroadcast(
                        context,
                        reminder.id.hashCode(),
                        intent,
                        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                    )

                    // Schedule exact alarm if possible, otherwise use best-effort fallback
                    try {
                        if (canScheduleExactAlarms()) {
                            alarmManager.setExactAndAllowWhileIdle(
                                AlarmManager.RTC_WAKEUP,
                                reminder.reminderTime,
                                pendingIntent
                            )
                        } else {
                            alarmManager.set(
                                AlarmManager.RTC_WAKEUP,
                                reminder.reminderTime,
                                pendingIntent
                            )
                        }
                    } catch (e: SecurityException) {
                        Log.w(TAG, "⚠️ SecurityException rescheduling alarm for ${reminder.id}: ${e.message}")
                        // Best-effort fallback
                        alarmManager.set(
                            AlarmManager.RTC_WAKEUP,
                            reminder.reminderTime,
                            pendingIntent
                        )
                    }
                    rescheduledCount++
                } else {
                    // Mark expired reminders as inactive - Fixed using deactivateReminder
                    reminderDao.deactivateReminder(reminder.id)
                }
            }

            Log.d(TAG, " Rescheduled $rescheduledCount reminders after reboot")
            Result.success("Rescheduled $rescheduledCount reminders")

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error rescheduling reminders", e)
            Result.failure(e)
        }
    }

    /**
     * Create a reminder from AI detection
     * This is a convenience method that wraps scheduleReminder with proper error handling
     */
    suspend fun createReminderFromDetection(
        detectedReminder: DetectedReminder,
        noteId: String
    ): Boolean {
        return try {
            val result = scheduleReminder(detectedReminder, noteId)
            result.isSuccess
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error creating reminder from detection", e)
            false
        }
    }

    /**
     * Check if the app can schedule exact alarms
     */
    fun canScheduleExactAlarms(): Boolean {
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            alarmManager.canScheduleExactAlarms()
        } else {
            true
        }
    }

    /**
     * Open system settings to allow the user to grant exact alarm permission (Android 12+).
     * Returns true if the intent was launched, false if not needed or not applicable.
     */
    fun requestExactAlarmPermission(): Boolean {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S && !canScheduleExactAlarms()) {
            try {
                val intent = Intent(
                    android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,
                    android.net.Uri.parse("package:${context.packageName}")
                ).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
                context.startActivity(intent)
                return true
            } catch (e: Exception) {
                Log.e(TAG, "❌ Error opening exact alarm settings", e)
            }
        }
        return false
    }

    /**
     * Show notification for triggered reminder
     */
    fun showReminderNotification(
        reminderId: String,
        title: String,
        description: String,
        noteId: String
    ) {
        try {
            // Check notification permissions first
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                val notificationManager = NotificationManagerCompat.from(context)
                if (!notificationManager.areNotificationsEnabled()) {
                    Log.w(TAG, "⚠️ Notifications are disabled for this app")
                    return
                }
            }

            // Create intent to open the note
            val notificationIntent = Intent(context, MainActivity::class.java).apply {
                putExtra("noteId", noteId)
                flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
            }

            val pendingIntent = PendingIntent.getActivity(
                context,
                reminderId.hashCode(),
                notificationIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
            )

            val notification = NotificationCompat.Builder(context, NOTIFICATION_CHANNEL_ID)
                .setSmallIcon( R.drawable.logo2)
                .setContentTitle(" $title")
                .setContentText(description)
                .setPriority(NotificationCompat.PRIORITY_HIGH)
                .setCategory(NotificationCompat.CATEGORY_REMINDER)
                .setAutoCancel(true)
                .setContentIntent(pendingIntent)
                .setVibrate(longArrayOf(0, 500, 100, 500))
                .setDefaults(NotificationCompat.DEFAULT_SOUND or NotificationCompat.DEFAULT_LIGHTS)
                .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
                .setOnlyAlertOnce(false)
                .build()

            val notificationManager = NotificationManagerCompat.from(context)
            try {
                notificationManager.notify(reminderId.hashCode(), notification)
                Log.d(TAG, " Reminder notification shown: $title")

                // Mark reminder as completed in database - Fixed using deactivateReminder
                managerScope.launch {
                    try {
                        reminderDao.deactivateReminder(reminderId)
                        Log.d(TAG, "✅ Reminder marked as completed: $title")
                    } catch (e: Exception) {
                        Log.e(TAG, "❌ Error marking reminder as completed", e)
                    }
                }
            } catch (e: SecurityException) {
                Log.e(TAG, "❌ Missing notification permission", e)
            }

        } catch (e: Exception) {
            Log.e(TAG, "❌ Error showing reminder notification", e)
        }
    }
}

