                if (remindersSnapshot.exists()) {
                    for (reminderChild in remindersSnapshot.children) {
                        try {
                            val reminderData = reminderChild.getValue(ReminderEntity::class.java)
                            if (reminderData != null) {
                                reminderDao.insertReminder(reminderData)
